import argparse
import csv
import json
from datetime import datetime

DATE_FORMATS = [
    "%Y-%m-%d",
    "%m/%d/%Y",
    "%d/%m/%Y",
    "%Y/%m/%d",
]

def parse_date(text):
    text = text.strip()
    for fmt in DATE_FORMATS:
        try:
            return datetime.strptime(text, fmt)
        except ValueError:
            continue
    raise ValueError(f"Cannot parse date: {text!r}")

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    payload = json.loads(args.payload) if args.payload else {}
    path = payload.get("path", "/inputs/dates.csv")

    dates = []
    with open(path, newline="") as f:
        reader = csv.DictReader(f)
        if reader.fieldnames is None:
            print(0)
            return

        date_col = None
        for name in reader.fieldnames:
            if name.strip().lower() == "date":
                date_col = name
                break

        if date_col is None:
            raise ValueError("No 'date' column found in CSV")

        for row in reader:
            value = row.get(date_col)
            if value is None or value.strip() == "":
                continue
            dates.append(parse_date(value))

    if not dates:
        print(0)
        return

    earliest = min(dates)
    latest = max(dates)
    print((latest - earliest).days)

if __name__ == "__main__":
    main()

import argparse
import json
import csv
from decimal import Decimal, InvalidOperation


def read_csv(path):
    with open(path, newline="") as f:
        return list(csv.DictReader(f))


def find_column(row, candidates):
    lower_map = {k.lower(): k for k in row.keys()}
    for name in candidates:
        if name.lower() in lower_map:
            return lower_map[name.lower()]
    return None


def parse_amount(value):
    try:
        return Decimal(value)
    except (InvalidOperation, TypeError):
        return None


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    cfg = json.loads(args.payload)

    customers = read_csv(cfg["customers"])
    orders = read_csv(cfg["orders"])

    west_customer_ids = set()
    if customers:
        id_col = find_column(customers[0], ["customer_id"])
        region_col = find_column(customers[0], ["region"])
        if id_col and region_col:
            for row in customers:
                if row.get(region_col) == "west":
                    west_customer_ids.add(row[id_col])

    total = Decimal("0")
    if orders:
        cust_col = find_column(orders[0], ["customer_id"])
        amount_col = find_column(orders[0], ["amount"])
        if cust_col and amount_col:
            for row in orders:
                if row.get(cust_col) in west_customer_ids:
                    amount = parse_amount(row.get(amount_col))
                    if amount is not None:
                        total += amount

    if total == total.to_integral():
        print(int(total), end="")
    else:
        print(total, end="")


if __name__ == "__main__":
    main()

