import argparse
import json
import csv
from decimal import Decimal, InvalidOperation

LEDGER = "/inputs/ledger.csv"


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    parsed = parser.parse_args()
    json.loads(parsed.payload)  # tool reads a fixed input path; args are ignored

    total = Decimal("0")
    try:
        with open(LEDGER, "r", newline="") as f:
            lines = [line for line in f if line.strip()]
    except FileNotFoundError:
        lines = []

    if lines:
        reader = csv.reader(lines)
        header = next(reader, [])
        try:
            amount_idx = [h.strip().lower() for h in header].index("amount")
        except ValueError:
            amount_idx = None

        if amount_idx is not None:
            for row in reader:
                if amount_idx >= len(row):
                    continue
                raw = row[amount_idx].strip()
                if not raw:
                    continue
                raw = raw.lstrip("$").replace(",", "")
                try:
                    total += Decimal(raw)
                except InvalidOperation:
                    continue

    print(f"{total:.2f}", end="")


if __name__ == "__main__":
    main()

