    latest_action = {}
    latest_ts = {}

    try:
        with open("/inputs/events2.jsonl", "r", encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if not line:
                    continue
                record = json.loads(line)
                user = record["user"]
                action = record["action"]
                ts = record["ts"]
                if user not in latest_ts or ts > latest_ts[user]:
                    latest_ts[user] = ts
                    latest_action[user] = action
    except FileNotFoundError:
        pass

    logout_count = sum(1 for a in latest_action.values() if a == "logout")
    print(logout_count)


