import argparse
import csv
import json
from decimal import Decimal

def parse_amount(raw):
    if raw is None:
        return None
    s = raw.strip().replace(',', '').replace('$', '')
    if not s or s == '-':
        return None
    if s.endswith('-'):
        s = '-' + s[:-1]
    try:
        return Decimal(s)
    except Exception:
        return None

