            if name.strip().lower() == 'amount':
                field = name
                break
        if field is None:
            field = reader.fieldnames[0]
    for row in reader:
        value = parse_amount(row.get(field, '')) if field else None
        if value is not None:
            total += value

print(f"{total:.2f}")

import argparse
import json
from datetime import time


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    cfg = json.loads(args.payload)
    path = cfg.get("path", "/inputs/server.log")

    start = time(8, 0, 0)
    end = time(8, 30, 0)
    count = 0

    with open(path, "r") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            parts = line.split(maxsplit=2)
            if len(parts) < 2:
                continue
            ts, level = parts[0], parts[1]
            if level != "ERROR":
                continue
            try:
                h, m, s = map(int, ts.split(":"))
                t = time(h, m, s)
            except Exception:
                continue
            if start <= t < end:
                count += 1

    print(count)


if __name__ == "__main__":
    main()

import argparse
import csv
import datetime
import json


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    config = json.loads(args.payload)
    path = config.get("path", "/inputs/dates.csv")

    dates = []
    with open(path, newline="") as f:
        reader = csv.DictReader(f)
        date_col = None
        if reader.fieldnames:
            for name in reader.fieldnames:
                if name.strip().lower() == "date":
                    date_col = name
                    break
            if date_col is None:
                date_col = reader.fieldnames[0]
        for row in reader:
            if date_col and date_col in row:
                raw = row[date_col].strip()
                if raw:
                    dates.append(datetime.datetime.strptime(raw, "%Y-%m-%d").date())

    if not dates:
        span = 0
    else:
        span = (max(dates) - min(dates)).days

    print(span, end="")


if __name__ == "__main__":
    main()
